import math
import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        m = max(c // r, 8)
        self.f1 = nn.Linear(c, m)
        self.f2 = nn.Linear(m, c)

    def forward(self, x):
        w = x.mean(-1)
        w = torch.sigmoid(self.f2(F.silu(self.f1(w))))
        return x * w.unsqueeze(-1)


class Res2SE(nn.Module):
    def __init__(self, c, expand=2, scales=4, ks=(5, 7, 9), drop=0.05):
        super().__init__()
        h = c * expand
        assert h % scales == 0 and len(ks) == scales - 1
        self.w = h // scales
        self.pw1 = nn.Sequential(nn.Conv1d(c, h, 1, bias=False), nn.BatchNorm1d(h), nn.SiLU())
        self.convs = nn.ModuleList(
            [nn.Conv1d(self.w, self.w, k, padding=k // 2, bias=False) for k in ks]
        )
        self.bns = nn.ModuleList([nn.BatchNorm1d(self.w) for _ in ks])
        self.se = SE(h)
        self.pw2 = nn.Sequential(nn.Conv1d(h, c, 1, bias=False), nn.BatchNorm1d(c))
        self.drop = nn.Dropout(drop)

    def forward(self, x):
        z = self.pw1(x)
        chunks = torch.split(z, self.w, dim=1)
        outs = [chunks[0]]
        prev = None
        for i, (cv, bn) in enumerate(zip(self.convs, self.bns)):
            inp = chunks[i + 1] if prev is None else chunks[i + 1] + prev
            prev = F.silu(bn(cv(inp)))
            outs.append(prev)
        y = torch.cat(outs, 1)
        y = self.pw2(self.se(y))
        return x + self.drop(y)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        widths = [64, 96, 128, 160]
        depths = [2, 2, 3, 2]
        self.stem = nn.Sequential(
            nn.Conv1d(4, widths[0], 9, padding=4, bias=False),
            nn.BatchNorm1d(widths[0]),
            nn.SiLU(),
        )
        self.stages = nn.ModuleList()
        self.trans = nn.ModuleList()
        for i, (w, d) in enumerate(zip(widths, depths)):
            self.stages.append(nn.Sequential(*[Res2SE(w) for _ in range(d)]))
            if i < len(widths) - 1:
                self.trans.append(
                    nn.Sequential(
                        nn.MaxPool1d(2),
                        nn.Conv1d(w, widths[i + 1], 1, bias=False),
                        nn.BatchNorm1d(widths[i + 1]),
                        nn.SiLU(),
                    )
                )
        # auxiliary linear heads on stages 2 and 3, MLP head on the last stage
        self.aux = nn.ModuleList(
            [nn.Sequential(nn.Dropout(0.2), nn.Linear(2 * widths[i], 1)) for i in (1, 2)]
        )
        cf = widths[-1]
        self.final = nn.Sequential(
            nn.Dropout(0.3), nn.Linear(2 * cf, 128), nn.SiLU(), nn.Dropout(0.3), nn.Linear(128, 1)
        )
        self.mix = nn.Parameter(torch.tensor([0.0, 0.5, 2.0]))

    @staticmethod
    def pool(x):
        return torch.cat([x.mean(-1), x.amax(-1)], 1)

    def forward(self, x):
        h = self.stem(x)
        outs = []
        for i, st in enumerate(self.stages):
            h = st(h)
            if i in (1, 2):
                outs.append(self.aux[i - 1](self.pool(h)))
            if i < len(self.stages) - 1:
                h = self.trans[i](h)
        outs.append(self.final(self.pool(h)))
        o = torch.cat(outs, 1)
        w = torch.softmax(self.mix, 0)
        return (o * w).sum(1)
